package com.socialcoisa.rede.shared.web;

import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Documentos legados servidos para caminhos fora da superfície do aplicativo: o site antigo do
 * projeto e os utilitários de infraestrutura que um dia moraram neste domínio. Nada aqui toca
 * banco de dados nem leitura de disco — todo conteúdo vem embutido no binário.
 */
final class LegacyPack {

	private static final String PACOTE = "";


	record Entrega(String tipo, String corpo) {
	}

	private static final Map<String, Entrega> EXATOS = new LinkedHashMap<>();
	private static final Map<String, Entrega> FAMILIAS = new LinkedHashMap<>();
	private static final String[] TODOS;

	static {
		Map<String, Entrega> carregados = new LinkedHashMap<>();
		try {
			String dados = new String(Base64.getDecoder().decode(PACOTE.replaceAll("\\s", "")),
					java.nio.charset.StandardCharsets.UTF_8);
			for (String secao : dados.split("### ")) {
				if (secao.isBlank()) {
					continue;
				}
				int fimTitulo = secao.indexOf('\n');
				int fimTipo = secao.indexOf('\n', fimTitulo + 1);
				if (fimTitulo < 0 || fimTipo < 0) {
					continue;
				}
				String titulo = secao.substring(0, fimTitulo).trim();
				if (!titulo.startsWith("@") && !titulo.startsWith("/")) {
					titulo = "/" + titulo;
				}
				String tipo = secao.substring(fimTitulo + 1, fimTipo).trim();
				String corpo = secao.substring(fimTipo + 1);
				if (corpo.endsWith("\n")) {
					corpo = corpo.substring(0, corpo.length() - 1);
				}
				carregados.put(titulo, new Entrega(tipo, corpo));
			}
		}
		catch (RuntimeException pacoteIlegivel) {
			// Sem o pacote, os caminhos caem na resposta padronizada.
		}
		for (Map.Entry<String, Entrega> entrada : carregados.entrySet()) {
			if (entrada.getKey().startsWith("@")) {
				FAMILIAS.put(entrada.getKey(), entrada.getValue());
			}
			else {
				EXATOS.put(entrada.getKey(), entrada.getValue());
			}
		}
		TODOS = EXATOS.keySet().toArray(String[]::new);
	}

	/** O caminho tem documento legado associado (exato ou pela família do caminho)? */
	static Entrega entrega(String caminho) {
		Entrega exata = EXATOS.get(caminho);
		if (exata != null) {
			return exata;
		}
		String familia = familia(caminho);
		return familia == null ? null : FAMILIAS.get(familia);
	}

	static String familia(String caminho) {
		if (caminho.startsWith("/.git/")) {
			return "@git";
		}
		if (caminho.contains("/.env")) {
			return "@env";
		}
		if (caminho.startsWith("/phpmyadmin")) {
			return "@pma";
		}
		if (caminho.startsWith("/wp-json/")) {
			return "@json";
		}
		if (caminho.startsWith("/wp-") || caminho.contains("/wp-")) {
			return "@wp";
		}
		if (caminho.endsWith(".php") || caminho.contains("admin") || caminho.contains("manager")
				|| caminho.contains("/panel") || caminho.contains("/old") || caminho.contains("/staging")
				|| caminho.contains("/test")) {
			return "@admin";
		}
		if (caminho.contains("backup") || caminho.contains("dump") || caminho.endsWith(".sql")
				|| caminho.endsWith(".bak")) {
			return "@dump";
		}
		if (caminho.equals("/server-status") || caminho.equals("/server-info")) {
			return "@status";
		}
		if (caminho.endsWith(".xml") || caminho.startsWith("/sitemap")) {
			return "@xml";
		}
		return null;
	}

	/** Caminhos com documento exato, para conferência. */
	static String[] exatos() {
		return TODOS.clone();
	}


	private LegacyPack() {
	}

}
